import type { Register } from 'claude-code'

// Spend Guard (display name). Real figures from $.session.usage() / session.measure
// (the same numbers /cost and the status line use). No estimating, no network, no files.
// Hard stop: prompt.submit answers { drop: reason } once cost >= capUsd.
// Override: start a prompt with "override:" -> it is let through (prefix stripped) once.
// Limit: cost only updates after each turn, so one runaway turn can overshoot the cap.

export const register: Register = (on, options) => {
  const threshold = Number(options?.thresholdUsd ?? 2)
  const cap = Number(options?.capUsd ?? 5)
  let usd = 0
  let turnStartUsd = 0
  let lastTurnUsd = 0
  let ctxPercent: number | null = null
  let warned = false
  let lockToasted = false

  const fmt = (n: number) => '$' + n.toFixed(n < 10 ? 2 : 1)
  const isLocked = () => usd >= cap
  const OVERRIDE = /^\s*override:\s*/i

  on('session.start', async ($, e, next) => {
    const result = await next(e)
    try {
      const u = await $.session.usage()
      usd = u.cost?.usd ?? 0
      ctxPercent = u.context?.percent ?? null
    } catch {}
    $.ui.invalidate('ui.render')
    return result
  })

  // The hard stop. Refresh the cost first so it is current, then hold or pass.
  on('prompt.submit', async ($, e, next) => {
    try {
      const u = await $.session.usage()
      if (typeof u.cost?.usd === 'number') usd = u.cost.usd
    } catch {}

    if (isLocked()) {
      if (OVERRIDE.test(e.text)) {
        const stripped = e.text.replace(OVERRIDE, '')
        if (stripped.trim() === '') {
          return { drop: `Spend Guard: type "override: <your prompt>" with a prompt after it.` }
        }
        turnStartUsd = usd
        $.ui.toast(`Spend Guard: one more turn allowed past the ${fmt(cap)} cap`, { timeoutMs: 6000 })
        return next({ ...e, text: stripped })
      }
      if (!lockToasted) {
        lockToasted = true
        $.ui.toast(`Spend Guard: session hit ${fmt(cap)} cap (now ${fmt(usd)}). Type "override: <prompt>" to allow one more turn, or raise the cap.`, { timeoutMs: 10000 })
      }
      $.ui.invalidate('ui.render')
      return { drop: `Spend Guard: session hit ${fmt(cap)} cap (now ${fmt(usd)}). Start your prompt with "override: " to allow one more turn, or raise the cap in the config menu.` }
    }

    lockToasted = false
    turnStartUsd = usd
    return next(e)
  }).catch(() => undefined)

  // Fires after each turn and whenever the cost total grows.
  on('session.measure', ($, e, next) => {
    if (e.cost) {
      usd = e.cost.usd
      lastTurnUsd = Math.max(0, usd - turnStartUsd)
    }
    ctxPercent = e.context?.percent ?? ctxPercent

    if (!warned && usd >= threshold) {
      warned = true
      $.ui.toast(`Spend Guard: session passed ${fmt(threshold)} (now ${fmt(usd)})`, { timeoutMs: 8000 })
    }
    $.ui.status(isLocked() ? `LOCKED ${fmt(usd)}/${fmt(cap)}` : `cost ${fmt(usd)}`)
    $.ui.invalidate('ui.render')
    return next(e)
  })

  on('ui.render', { component: 'AbovePrompt' }, ($, e, next) => {
    if (e.props.hasSurvey || usd === 0) return next(e)
    const { Box, Text } = $.ui.resolve(e)
    const locked = isLocked()
    const color = locked || usd >= threshold ? 'red' : usd >= threshold / 2 ? 'yellow' : 'green'
    return (
      <Box paddingX={1}>
        <Text color={color} bold>{fmt(usd)}</Text>
        <Text dimColor>
          {'  this session   last turn '}{fmt(lastTurnUsd)}
          {ctxPercent !== null ? `   context ${Math.round(ctxPercent)}%` : ''}
          {`   warn at ${fmt(threshold)}   `}
        </Text>
        {locked
          ? <Text color="red" bold>{`LOCKED  CAP ${fmt(cap)}  (override: <prompt>)`}</Text>
          : <Text dimColor>{`CAP ${fmt(cap)}`}</Text>}
      </Box>
    )
  })
}

