{
  "name": "spend-guard",
  "version": "0.2.0",
  "description": "Spend Guard: live session cost band, a warning toast, and a hard stop that holds your next prompt once the session hits a dollar cap.",
  "userConfig": {
    "thresholdUsd": {
      "type": "number",
      "title": "Warning threshold (USD)",
      "description": "Show a warning toast once the session cost crosses this many dollars.",
      "default": 2
    },
    "capUsd": {
      "type": "number",
      "title": "Spend cap (USD)",
      "description": "Hard stop: once the session cost is at or over this, the next prompt is held. Type 'override: your prompt' to allow one more turn, or raise the cap.",
      "default": 5
    }
  },
  "author": {
    "name": "Build & Bloom"
  }
}
